/* built by build.sh from src/*.cpp and web/* - do not edit */
var SIM_B64 = "";
/* Emberstones - the sound. Everything is synthesised with the Web Audio API:
 * noise through filters for wind and water, oscillators for the stones. The
 * page starts silent; the sound button wakes the AudioContext and the bed
 * fades in at once. */
'use strict';

var EmberAudio = (function () {
  var ctx = null, master = null, comp = null, noise = null;
  var on = false, bed = null, levels = null;

  /* a pentatonic ladder, so any two stones struck together still agree */
  var LADDER = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];
  var BASE = 196.0;                       /* G3 */

  function hz(semis) { return BASE * Math.pow(2, semis / 12); }

  function makeNoise() {
    var len = ctx.sampleRate * 2;
    var buf = ctx.createBuffer(1, len, ctx.sampleRate);
    var d = buf.getChannelData(0);
    for (var i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    return buf;
  }

  function chain() {
    comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14; comp.knee.value = 18;
    comp.ratio.value = 6; comp.attack.value = 0.004; comp.release.value = 0.25;
    master = ctx.createGain(); master.gain.value = 0.0;
    master.connect(comp); comp.connect(ctx.destination);
  }

  function loopNoise(gain, freq, q, type) {
    var src = ctx.createBufferSource();
    src.buffer = noise; src.loop = true;
    var f = ctx.createBiquadFilter();
    f.type = type; f.frequency.value = freq; f.Q.value = q;
    var g = ctx.createGain(); g.gain.value = gain;
    src.connect(f); f.connect(g); g.connect(master);
    src.start();
    return { src: src, filter: f, gain: g };
  }

  function pad(freq, gain, type) {
    var o = ctx.createOscillator(); o.type = type; o.frequency.value = freq;
    var g = ctx.createGain(); g.gain.value = 0;
    o.connect(g); g.connect(master); o.start();
    return { osc: o, gain: g };
  }

  /* the bed: wind, water and a slow pad. Three layers, each moved by the scene. */
  function buildBed() {
    var wind = loopNoise(0.0, 420, 0.7, 'lowpass');
    var water = loopNoise(0.0, 1400, 1.6, 'bandpass');
    var drone = pad(hz(0), 0.0, 'sine');
    var fifth = pad(hz(7), 0.0, 'sine');
    var lfo = ctx.createOscillator(); lfo.frequency.value = 0.07;
    var lfoG = ctx.createGain(); lfoG.gain.value = 220;
    lfo.connect(lfoG); lfoG.connect(wind.filter.frequency); lfo.start();
    var trem = ctx.createOscillator(); trem.frequency.value = 0.11;
    var tremG = ctx.createGain(); tremG.gain.value = 0.35;
    trem.connect(tremG); tremG.connect(water.gain.gain); trem.start();
    return { wind: wind, water: water, drone: drone, fifth: fifth, lfo: lfo, trem: trem };
  }

  function ramp(param, to, sec) {
    var t = ctx.currentTime;
    param.cancelScheduledValues(t);
    param.setValueAtTime(param.value, t);
    param.linearRampToValueAtTime(to, t + sec);
  }

  /* called every frame with the scene's own numbers */
  function scene(litFrac, level, motion) {
    if (!on || !bed) return;
    var lv = Math.max(0, Math.min(1, litFrac));
    ramp(bed.wind.gain.gain, 0.045 + 0.05 * motion, 0.9);
    ramp(bed.water.gain.gain, 0.006 + 0.030 * lv, 1.2);
    ramp(bed.drone.gain.gain, 0.020 + 0.030 * lv, 1.4);
    ramp(bed.fifth.gain.gain, 0.006 + 0.016 * lv, 1.4);
    var chord = [0, 2, 5, 7, 9, 12][Math.min(5, Math.max(0, level))];
    ramp(bed.drone.osc.frequency, hz(chord), 2.0);
    ramp(bed.fifth.osc.frequency, hz(chord + 7), 2.0);
  }

  /* one short note: frequency, length, loudness, waveform. A record, so the
     voices below read as data and every call stays two arguments. */
  function note(f, d, v, t) { return { f: f, d: d, v: v, t: t || 'triangle' }; }

  function ping(t0, n) {
    var o = ctx.createOscillator(); o.type = n.t;
    var g = ctx.createGain();
    o.frequency.setValueAtTime(n.f, t0);
    if (n.bend) o.frequency.exponentialRampToValueAtTime(n.f * n.bend, t0 + n.d);
    g.gain.setValueAtTime(n.bend ? n.v : 0.0001, t0);
    if (!n.bend) g.gain.exponentialRampToValueAtTime(n.v, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + n.d);
    o.connect(g); g.connect(master); o.start(t0); o.stop(t0 + n.d + 0.05);
    return o;
  }

  /* the same voice, falling: a body rather than a bell */
  function thud(t0, n) { return ping(t0, { f: n.f, d: n.d, v: n.v, t: 'sine', bend: 0.55 }); }

  function hiss(t0, n, q) {
    var src = ctx.createBufferSource(); src.buffer = noise;
    var f = ctx.createBiquadFilter(); f.type = 'bandpass';
    f.frequency.value = n.f; f.Q.value = q || 1.2;
    var g = ctx.createGain();
    g.gain.setValueAtTime(n.v, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + n.d);
    src.connect(f); f.connect(g); g.connect(master);
    src.start(t0); src.stop(t0 + n.d + 0.05);
  }

  /* one voice per event type. a table, so the mixer stays short. */
  var VOICES = {
    1: function (t, a) { ping(t, note(hz(LADDER[a % LADDER.length]), 0.55, 0.20)); hiss(t, note(2600, 0.09, 0.05), 2.4); },
    2: function (t) { thud(t, note(110, 0.22, 0.16)); hiss(t, note(700, 0.18, 0.10), 0.8); },
    3: function (t) { [0, 4, 7, 12].forEach(function (n, i) { ping(t + i * 0.09, note(hz(n + 12), 0.9, 0.16)); }); },
    4: function (t) { ping(t, note(hz(9), 0.30, 0.12)); ping(t + 0.08, note(hz(4), 0.40, 0.12)); },
    5: function (t) { hiss(t, note(500, 0.35, 0.12), 0.7); thud(t, note(140, 0.30, 0.12)); },
    6: function (t) { [0, 5, 12].forEach(function (n, i) { ping(t + i * 0.11, note(hz(n), 1.1, 0.14)); }); },
    7: function (t) { ping(t, note(hz(19), 1.4, 0.13)); ping(t + 0.02, note(hz(24), 1.6, 0.09)); },
    8: function (t) { thud(t, note(72, 1.2, 0.28)); hiss(t, note(900, 0.9, 0.14), 0.6); ping(t + 0.1, note(hz(12), 2.2, 0.10)); },
    9: function (t) { [0, 7, 12, 16].forEach(function (n, i) { ping(t + i * 0.35, note(hz(n), 2.4, 0.12)); }); },
    10: function (t) { hiss(t, note(1100, 0.12, 0.07), 0.9); },
    11: function (t) { ping(t, note(hz(26), 2.0, 0.05)); }
  };

  function play(type, a, b) {
    if (!on || !ctx) return;
    var v = VOICES[type];
    if (v) v(ctx.currentTime + 0.001, a || 0, b || 0);
  }

  function chime() {
    var t = ctx.currentTime + 0.01;
    [0, 7, 12].forEach(function (n, i) { ping(t + i * 0.07, note(hz(n + 12), 0.7, 0.18)); });
  }

  function ensureCtx() {
    if (ctx) return;
    ctx = new (window.AudioContext || window.webkitAudioContext)();
    chain(); noise = makeNoise();
  }

  function wake() {
    ensureCtx();
    if (ctx.state === 'suspended') ctx.resume();
    on = true;
    if (!bed) bed = buildBed();
    ramp(master.gain, 0.62, 0.4);
    chime();
  }

  function hush() {
    on = false;
    if (master) ramp(master.gain, 0.0, 0.25);
  }

  function setOn(next) {
    if (next === on) return on;
    if (next) wake(); else hush();
    return on;
  }

  function suspended() { return ctx && ctx.state === 'suspended'; }
  function resume() {
    if (!on) return;
    if (suspended()) ctx.resume();
  }
  function isOn() { return on; }

  return { setOn: setOn, play: play, scene: scene, resume: resume, isOn: isOn };
})();

/* Emberstones - the page: load the wasm, paint its framebuffer, turn gestures
 * into calls, and hand the sim's events to the synth. */
'use strict';

(function () {
  var MAXW = 520, MAXH = 900;
  var S = null, cv = null, g2 = null, img = null;
  var simW = 0, simH = 0, ptr = 0, stride = 0;
  var pressed = false, dragTap = false, lastStone = -1, startX = 0, startY = 0;
  var suppress = 0, soundWanted = false, hinted = false, last = 0;

  var el = {};

  function decode(b64) {
    var bin = atob(b64), out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function boot() {
    el.stage = document.getElementById('stage');
    el.title = document.getElementById('title');
    el.say = document.getElementById('say');
    el.sound = document.getElementById('sound');
    el.undo = document.getElementById('undo');
    el.again = document.getElementById('again');
    cv = document.getElementById('c');
    g2 = cv.getContext('2d', { alpha: false });
    S = new WebAssembly.Instance(new WebAssembly.Module(decode(SIM_B64)), {}).exports;
    S.init();
    S.seed(visitSeed());
    layout();
    bind();
    last = performance.now();
    requestAnimationFrame(frame);
  }

  /* a fresh circle for each visit, but a reload keeps the same one */
  function visitSeed() {
    var saved = 0;
    try { saved = parseInt(localStorage.getItem('ember.seed') || '0', 10) || 0; } catch (e) { saved = 0; }
    if (!saved) {
      saved = (Date.now() ^ (Math.random() * 0xffffffff)) >>> 0;
      try { localStorage.setItem('ember.seed', String(saved)); } catch (e) { /* private mode */ }
    }
    return saved >>> 0;
  }

  function layout() {
    var vw = Math.max(220, window.innerWidth), vh = Math.max(320, window.innerHeight);
    var aspect = 0.70;                       /* keep a portrait stage on wide screens */
    var w = vw, h = vh;
    if (w / h > aspect) w = h * aspect;   /* wide screens: keep the portrait column, never shrink height */
    w = Math.round(w); h = Math.round(h);
    el.stage.style.width = w + 'px';
    el.stage.style.height = h + 'px';
    var k = Math.min(1, MAXW / w, MAXH / h);
    simW = Math.max(160, Math.round(w * k));
    simH = Math.max(240, Math.round(h * k));
    cv.width = simW; cv.height = simH;
    S.resize(simW, simH);
    ptr = S.rgbaPtr(); stride = S.stride();
    img = g2.createImageData(simW, simH);
  }

  function blit() {
    var src = new Uint8Array(S.memory.buffer, ptr, simH * stride);
    var dst = img.data, row = simW * 4;
    for (var y = 0; y < simH; y++) dst.set(src.subarray(y * stride, y * stride + row), y * row);
    g2.putImageData(img, 0, 0);
  }

  function toSim(e) {
    var r = cv.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) * simW / r.width,
      y: (e.clientY - r.top) * simH / r.height
    };
  }

  function say(text, ms) {
    if (!text) { el.say.classList.remove('on'); return; }
    el.say.textContent = text;
    el.say.classList.add('on');
    clearTimeout(say.t);
    say.t = setTimeout(function () { el.say.classList.remove('on'); }, ms || 4200);
  }

  function firstTouch() {
    el.title.classList.add('gone');
    if (!hinted) {
      hinted = true;
      say('tap a stone to wake it · hold one to ask which', 5200);
    }
    if (soundWanted && !EmberAudio.isOn()) setSound(true);
  }

  function setSound(on) {
    var now = EmberAudio.setOn(on);
    el.sound.setAttribute('aria-pressed', now ? 'true' : 'false');
    el.sound.setAttribute('aria-label', now ? 'Sound is on. Turn sound off.' : 'Sound is off. Turn sound on.');
    try { localStorage.setItem('ember.sound', now ? '1' : '0'); } catch (e) { /* private mode */ }
    if (now) say('the valley is listening', 2400);
    return now;
  }

  function onDown(e) {
    e.preventDefault();
    pressed = true; dragTap = false; lastStone = -1;
    var p = toSim(e);
    startX = p.x; startY = p.y;
    S.press(p.x, p.y);
    lastStone = S.stoneAt(p.x, p.y);
    firstTouch();
  }

  function onMove(e) {
    if (!pressed) return;
    var p = toSim(e);
    var dx = p.x - startX, dy = p.y - startY;
    if (dx * dx + dy * dy < 16) return;
    var s = S.stoneAt(p.x, p.y);
    if (s >= 0 && s !== lastStone) { S.tapStone(s); dragTap = true; lastStone = s; }
  }

  function onUp(e) {
    if (!pressed) return;
    pressed = false;
    if (dragTap) {
      S.release(-1000, -1000);       /* the drag already woke its stones */
      suppress = 2;
      dragTap = false;
      return;
    }
    var p = toSim(e);
    S.release(p.x, p.y);
  }

  function bind() {
    cv.addEventListener('pointerdown', onDown, { passive: false });
    cv.addEventListener('pointermove', onMove, { passive: true });
    cv.addEventListener('pointerup', onUp);
    cv.addEventListener('pointercancel', onUp);
    cv.addEventListener('contextmenu', function (e) { e.preventDefault(); });
    el.sound.addEventListener('click', function () { setSound(!EmberAudio.isOn()); });
    el.undo.addEventListener('click', function () { if (S.undoMove() >= 0) say('one stone taken back', 1800); });
    el.again.addEventListener('click', function () { S.restartLevel(); say('the circle is set again', 1800); });
    window.addEventListener('resize', function () { layout(); });
    window.addEventListener('orientationchange', function () { setTimeout(layout, 220); });
    window.addEventListener('visibilitychange', function () { if (!document.hidden) EmberAudio.resume(); });
    window.addEventListener('keydown', keys);
    try { soundWanted = localStorage.getItem('ember.sound') === '1'; } catch (e) { soundWanted = false; }
    if (soundWanted) el.sound.setAttribute('aria-label', 'Sound is off. Turn sound on.');
  }

  function keys(e) {
    var k = e.key.toLowerCase();
    if (k === 'm') setSound(!EmberAudio.isOn());
    else if (k === 'u') { if (S.undoMove() >= 0) say('one stone taken back', 1800); }
    else if (k === 'r') { S.restartLevel(); say('the circle is set again', 1800); }
  }

  var NOTES = {
    2: 'moss remembers a touch',
    3: 'the circle is awake — tap to go on',
    6: 'a deeper circle, and it is dark',
    7: 'that one is warm — it wants to be lit',
    8: 'the keystone is under your thumb',
    9: 'the sky is turning',
    11: 'something drifts in the dark'
  };

  function drain() {
    var n = S.nevents();
    if (n <= 0) return;
    var ev = new Int32Array(S.memory.buffer, S.eventPtr(), n * 3);
    for (var i = 0; i < n; i++) {
      var t = ev[i * 3], a = ev[i * 3 + 1];
      if (t === 10 && suppress > 0) continue;
      EmberAudio.play(t, a, ev[i * 3 + 2]);
      if (NOTES[t]) say(NOTES[t], t === 3 ? 5200 : 3400);
    }
    S.clearEvents();
    if (suppress > 0) suppress--;
  }

  function frame(t) {
    var dt = Math.min(0.05, Math.max(0, (t - last) / 1000));
    last = t;
    S.tick(dt);
    S.render();
    blit();
    drain();
    var n = S.stats(1);
    EmberAudio.scene(n ? S.stats(0) / n : 0, S.stats(2), S.stats(4) ? 1 : 0.6);
    requestAnimationFrame(frame);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
